PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "contributions" ("id" integer primary key autoincrement not null, "tontine_member_id" integer not null, "amount" numeric not null, "status" varchar check ("status" in ('pending', 'completed', 'failed', 'cancelled')) not null default 'pending', "transaction_reference" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, "round" integer not null default ('1'), "payment_method" varchar not null default ('mobile_money'), "commission_amount" numeric not null default ('0'), "transfer_code" varchar, "verification_status" varchar not null default ('not_applicable'), "submitted_at" datetime, "commission_rate" numeric, "currency" varchar not null default ('XOF'), "payment_failure_reason" varchar, foreign key("tontine_member_id") references tontine_members("id") on delete cascade on update no action);
CREATE TABLE "disputes" ("id" integer primary key autoincrement not null, "tontine_id" integer not null, "raised_by" integer not null, "subject" varchar not null, "description" text not null, "status" varchar check ("status" in ('open', 'resolved', 'rejected')) not null default 'open', "resolution_note" text, "resolved_by" integer, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("tontine_id") references "tontines"("id") on delete cascade, foreign key("raised_by") references "users"("id") on delete cascade, foreign key("resolved_by") references "users"("id") on delete set null);
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "installment_purchases" ("id" integer primary key autoincrement not null, "product_id" integer not null, "user_id" integer not null, "installments_count" integer not null, "installment_amount" numeric not null, "product_price" numeric not null, "status" varchar check ("status" in ('active', 'completed', 'cancelled')) not null default 'active', "delivery_status" varchar check ("delivery_status" in ('not_applicable', 'pending', 'delivered')) not null default 'not_applicable', "delivered_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "installments" ("id" integer primary key autoincrement not null, "installment_purchase_id" integer not null, "installment_number" integer not null, "amount" numeric not null, "commission_amount" numeric not null default '0', "payment_method" varchar, "status" varchar check ("status" in ('pending', 'completed', 'failed', 'cancelled')) not null default 'pending', "transaction_reference" varchar, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, "transfer_code" varchar, "verification_status" varchar check ("verification_status" in ('not_applicable', 'pending', 'accepted', 'rejected')) not null default 'not_applicable', "submitted_at" datetime, "commission_rate" numeric, "currency" varchar not null default 'XOF', "payment_failure_reason" varchar, foreign key("installment_purchase_id") references "installment_purchases"("id") on delete cascade);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "merchant_reviews" ("id" integer primary key autoincrement not null, "merchant_id" integer not null, "user_id" integer not null, "tontine_id" integer not null, "rating" integer not null, "comment" text, "created_at" datetime, "updated_at" datetime, foreign key("merchant_id") references "merchants"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("tontine_id") references "tontines"("id") on delete cascade);
CREATE TABLE "merchants" ("id" integer primary key autoincrement not null, "user_id" integer not null, "business_name" varchar not null, "address" varchar, "city" varchar, "description" text, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "rating" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "product_media" ("id" integer primary key autoincrement not null, "product_id" integer not null, "type" varchar check ("type" in ('image', 'video')) not null, "path" varchar not null, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "merchant_id" integer not null, "name" varchar not null, "description" text, "category" varchar, "price" numeric not null, "stock" integer not null default '0', "image" varchar, "status" varchar check ("status" in ('draft', 'published', 'archived')) not null default 'draft', "created_at" datetime, "updated_at" datetime, foreign key("merchant_id") references "merchants"("id") on delete cascade);
CREATE TABLE "refunds" ("id" integer primary key autoincrement not null, "contribution_id" integer not null, "tontine_id" integer not null, "user_id" integer not null, "amount" numeric not null, "status" varchar check ("status" in ('pending', 'processed')) not null default 'pending', "processed_by" integer, "processed_at" datetime, "created_at" datetime, "updated_at" datetime, "method" varchar check ("method" in ('manual')) not null default 'manual', "payment_reference" varchar, foreign key("contribution_id") references "contributions"("id") on delete cascade, foreign key("tontine_id") references "tontines"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("processed_by") references "users"("id") on delete set null);
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "tontine_members" ("id" integer primary key autoincrement not null, "tontine_id" integer not null, "user_id" integer not null, "position" integer, "status" varchar check ("status" in ('active', 'beneficiary', 'completed', 'withdrawn')) not null default 'active', "joined_at" datetime not null default (CURRENT_TIMESTAMP), "created_at" datetime, "updated_at" datetime, "delivery_status" varchar not null default ('not_applicable'), "delivered_at" datetime, "beneficiary_round" integer, foreign key("tontine_id") references tontines("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "tontines" ("id" integer primary key autoincrement not null, "product_id" integer, "created_by" integer not null, "name" varchar not null, "total_amount" numeric not null, "contribution_amount" numeric not null, "frequency" varchar check ("frequency" in ('daily', 'weekly', 'monthly')) not null default 'monthly', "max_members" integer not null, "status" varchar check ("status" in ('open', 'active', 'completed', 'cancelled')) not null default 'open', "start_date" date, "created_at" datetime, "updated_at" datetime, "current_round" integer not null default ('1'), "type" varchar check ("type" in ('product', 'cash')) not null default 'product', "commission_rate" numeric, foreign key("product_id") references products("id") on delete cascade on update no action, foreign key("created_by") references users("id") on delete cascade on update no action);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar check ("role" in ('client', 'merchant', 'admin')) not null default 'client', "phone" varchar, "is_verified" tinyint(1) not null default '0', "is_blocked" tinyint(1) not null default '0', "avatar_path" varchar);
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "contributions_round_status_index" on "contributions" ("round", "status");
CREATE INDEX "contributions_status_paid_at_index" on "contributions" ("status", "paid_at");
CREATE UNIQUE INDEX "contributions_tontine_member_id_round_unique" on "contributions" ("tontine_member_id", "round");
CREATE UNIQUE INDEX "contributions_transaction_reference_unique" on "contributions" ("transaction_reference");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "installments_installment_purchase_id_installment_number_unique" on "installments" ("installment_purchase_id", "installment_number");
CREATE INDEX "installments_status_paid_at_index" on "installments" ("status", "paid_at");
CREATE UNIQUE INDEX "installments_transaction_reference_unique" on "installments" ("transaction_reference");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "merchant_reviews_user_id_tontine_id_unique" on "merchant_reviews" ("user_id", "tontine_id");
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "refunds_contribution_id_unique" on "refunds" ("contribution_id");
CREATE INDEX "refunds_status_index" on "refunds" ("status");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "tontine_members_delivery_status_index" on "tontine_members" ("delivery_status");
CREATE UNIQUE INDEX tontine_members_single_beneficiary ON tontine_members (tontine_id) WHERE status = 'beneficiary';
CREATE UNIQUE INDEX "tontine_members_tontine_id_user_id_unique" on "tontine_members" ("tontine_id", "user_id");
CREATE UNIQUE INDEX "tontine_members_tontine_position_unique" on "tontine_members" ("tontine_id", "position");
CREATE INDEX "tontines_status_index" on "tontines" ("status");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_phone_unique" on "users" ("phone");
INSERT INTO "migrations" ("id", "migration", "batch") VALUES (1, '0001_01_01_000000_create_users_table', 1), (2, '0001_01_01_000001_create_cache_table', 1), (3, '0001_01_01_000002_create_jobs_table', 1), (4, '2024_01_01_000001_add_role_and_phone_to_users_table', 1), (5, '2024_01_01_000002_create_merchants_table', 1), (6, '2024_01_01_000003_create_products_table', 1), (7, '2024_01_01_000004_create_tontines_table', 1), (8, '2024_01_01_000005_create_tontine_members_table', 1), (9, '2024_01_01_000006_create_contributions_table', 1), (10, '2024_01_02_000001_add_current_round_to_tontines_table', 1), (11, '2024_01_02_000002_add_round_to_contributions_table', 1), (12, '2024_01_03_000001_add_delivery_status_to_tontine_members_table', 1), (13, '2024_01_04_000001_create_disputes_table', 1), (14, '2024_01_05_000001_make_product_optional_on_tontines_table', 1), (15, '2024_01_05_000002_change_payment_method_to_string_on_contributions_table', 1), (16, '2024_01_06_000001_create_notifications_table', 1), (17, '2024_01_07_000001_create_merchant_reviews_table', 1), (18, '2024_01_07_000002_create_refunds_table', 1), (19, '2024_01_07_000003_add_commission_amount_to_contributions_table', 1), (20, '2024_01_08_000001_add_is_blocked_to_users_table', 1), (21, '2024_01_09_000001_create_settings_table', 1), (22, '2024_01_10_000001_create_installment_purchases_table', 1), (23, '2024_01_10_000002_create_installments_table', 1), (24, '2024_01_11_000001_create_product_media_table', 1), (25, '2024_01_13_000001_add_transfer_verification_to_contributions_table', 1), (26, '2024_01_13_000002_add_transfer_verification_to_installments_table', 1), (27, '2026_08_06_080831_create_personal_access_tokens_table', 1), (28, '2026_09_25_000001_add_avatar_path_to_users_table', 1), (29, '2026_09_25_000002_sync_is_verified_with_email_verified_at', 1), (30, '2026_09_25_000003_add_payment_financial_fields', 1), (31, '2026_09_25_000004_add_cancelled_to_contributions_status', 1), (32, '2026_09_25_000005_add_payment_constraints', 1), (33, '2026_09_25_000006_harden_tontine_cycle', 1), (34, '2026_09_28_000001_restore_lost_enum_constraints', 1), (35, '2026_09_28_000002_guard_financial_amounts', 1), (36, '2026_09_28_000003_add_integrity_indexes', 1), (37, '2026_09_28_000004_enforce_single_beneficiary_per_tontine', 1);
COMMIT;
